		t.Fatal(got)
	}
	if i.calls != 2 {
		t.Fatalf("excess requests reached introspection: %d", i.calls)
	}
}
func TestGlobalBudgetBoundsRotatingIPs(t *testing.T) {
	h, i, _ := gatewayForTest(10, 2, 10)
	i.inactive = true
	requestGateway(h, "/api/v1/zones", "192.0.2.1", "sdpat_invalid")
