func deleteBindingsAndBump(ctx context.Context, tx store.Tx, bs []store.RoleBinding, includeOwner bool, skip ...store.Principal) ([]store.RoleBinding, error) {
	if len(bs) == 0 {
		return nil, nil
	}
	if err := lockUsers(ctx, tx, principalsOf(bs)); err != nil {
		return nil, err
	}
	var deleted []store.RoleBinding
	var err error
	if includeOwner {
		deleted, err = tx.DeleteBindingsIncludingOwner(ctx, bindingIDs(bs))
	} else {
		deleted, err = tx.DeleteBindings(ctx, bindingIDs(bs))
	}
	if err != nil {
