// Deleting an entire organization intentionally includes its owner binding.
func (t *tx) DeleteBindingsIncludingOwner(ctx context.Context, ids []uuid.UUID) ([]store.RoleBinding, error) {
	return t.deleteBindings(ctx, ids, "")
}

func (t *tx) deleteBindings(ctx context.Context, ids []uuid.UUID, predicate string) ([]store.RoleBinding, error) {
	if len(ids) == 0 {
		return []store.RoleBinding{}, nil
	}
	rows, err := t.q.Query(ctx, "DELETE FROM iam.role_bindings WHERE id = ANY($1)"+predicate+" RETURNING "+bindingCols, ids)
	return collect(rows, err, scanBinding)
}

func (t *tx) ListBindings(ctx context.Context, f store.BindingFilter, page store.Page) ([]store.RoleBinding, int, error) {
	var conds []string
	var args []any
	add := func(cond string, v any) {
		args = append(args, v)
		conds = append(conds, fmt.Sprintf(cond, len(args)))
	}
	if f.Principal != nil {
		add("principal_type = $%d", string(f.Principal.Type))
		add("principal_id = $%d", f.Principal.ID)
	}
	if f.ResourceType != "" {
		add("resource_type = $%d", string(f.ResourceType))
	}
	if f.ResourceID != nil {
		add("resource_id = $%d", *f.ResourceID)
	}
	if f.OrgID != nil {
		add("org_id = $%d", *f.OrgID)
	}
	where := ""
	if len(conds) > 0 {
		where = " WHERE " + strings.Join(conds, " AND ")
	}
	var total int
	if err := t.q.QueryRow(ctx, "SELECT count(*) FROM iam.role_bindings"+where, args...).Scan(&total); err != nil {
		return nil, 0, mapErr(err)
	}
	lo, args := limitOffset(page, args)
	rows, err := t.q.Query(ctx, "SELECT "+bindingCols+" FROM iam.role_bindings"+where+" ORDER BY created_at, id"+lo, args...)
